  dec_cenario -- "Possui Objeto Indireto (OI) preposicionado" --> dec_prop_b{"Qual pronome a banca inseriu na reescrita?"}
  dec_prop_b -- "Pronome de OI (lhe, a ele)" --> res_errado_b["Julgar ITEM ERRADO (Vício: Duplicidade OI + OI)"]
